<?php
require 'includes/auth.php'; require 'includes/db.php';
$stmt = $pdo->prepare('SELECT a.appointment_date, a.appointment_time, a.status, c.name AS centre_name FROM appointments a JOIN centres c ON c.id = a.centre_id WHERE a.donor_id = ? ORDER BY a.appointment_date DESC, a.appointment_time DESC LIMIT 5');
$stmt->execute([$_SESSION['donor_id']]); $appointments = $stmt->fetchAll();
$pageTitle='Dashboard'; include 'includes/header.php';
?>
<section class="container section"><p class="eyebrow">DONOR PORTAL</p><h1>Welcome, <?= htmlspecialchars($_SESSION['donor_name']) ?>!</h1><p>Manage your blood donation appointments and stay connected.</p><div class="cards"><div class="card"><h3>Book an Appointment</h3><p>Choose a centre and schedule your next donation.</p><a class="btn" href="appointments.php">Book Now</a></div><div class="card"><h3>My Appointments</h3><p>View your recent and upcoming bookings.</p><a class="btn btn-dark" href="appointments.php">View Appointments</a></div><div class="card"><h3>My Donor Profile</h3><p>View and update your personal information.</p><a class="btn btn-dark" href="profile.php">My Profile</a></div><div class="card"><h3>Donation History</h3><p>See your completed donations recorded by donation centres.</p><a class="btn btn-dark" href="donation_history.php">View History</a></div><div class="card"><h3>Emergency Alerts</h3><p>View active requests from participating donation centres.</p><a class="btn btn-dark" href="emergency_alerts.php">View Alerts</a></div></div><h2 class="section-heading">Recent Appointments</h2><?php if (!$appointments): ?><p>You have not booked any appointments yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Centre</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php foreach ($appointments as $item): ?><tr><td><?= htmlspecialchars($item['centre_name']) ?></td><td><?= htmlspecialchars($item['appointment_date']) ?></td><td><?= htmlspecialchars(substr($item['appointment_time'], 0, 5)) ?></td><td><?= htmlspecialchars($item['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
